mapper.update:
update talk_student
student_code = #{studentCode}, student_name = #{studentName}, dept_id = #{deptId}, gender = #{gender}, political_status = #{politicalStatus}, nation = #{nation}, phone = #{phone}, id_card = #{idCard}, address = #{address}, father_name = #{fatherName}, father_phone = #{fatherPhone}, mother_name = #{motherName}, mother_phone = #{motherPhone}, class_monitor = #{classMonitor}, dorm_leader = #{dormLeader}, dorm_building = #{dormBuilding}, dorm_room = #{dormRoom}, enrollment_status = #{enrollmentStatus}, mental_health_status = #{mentalHealthStatus}, poverty_level = #{povertyLevel}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime},
where student_id = #{studentId}

mapper.select:
select s.student_id, s.student_code, s.student_name, s.dept_id, s.gender, 
       s.political_status, s.nation, s.phone, s.id_card, s.address, s.father_name, 
       s.father_phone, s.mother_name, s.mother_phone, s.class_monitor, s.dorm_leader, 
       s.dorm_building, s.dorm_room, s.enrollment_status, s.mental_health_status, 
       s.poverty_level, s.remark, s.create_by, s.create_time, s.update_by, s.update_time,
       d.dept_name,
       (select max(ts.talk_time) 
        from talk_student_record tsr 
        join talk_session ts on tsr.session_id = ts.session_id 
        where tsr.student_id = s.student_id) as last_talk_time
from talk_student s
left join sys_dept d on s.dept_id = d.dept_id

     and s.student_code = #{studentCode}
     and s.student_name like concat('%', #{studentName}, '%')
     and s.dept_id = #{deptId}
     and s.gender = #{gender}
     and s.political_status = #{politicalStatus}
     and s.nation = #{nation}
     and s.phone = #{phone}
     and s.id_card = #{idCard}
     and s.address = #{address}
     and s.father_name like concat('%', #{fatherName}, '%')
     and s.father_phone = #{fatherPhone}
     and s.mother_name like concat('%', #{motherName}, '%')
     and s.mother_phone = #{motherPhone}
     and s.class_monitor = #{classMonitor}
     and s.dorm_leader = #{dormLeader}
     and s.dorm_building = #{dormBuilding}
     and s.dorm_room = #{dormRoom}
     and s.enrollment_status = #{enrollmentStatus}
     and s.mental_health_status = #{mentalHealthStatus}
     and s.poverty_level = #{povertyLevel}
     and d.dept_name in (select class_name from talk_teacher_class where teacher_code = #{params.counselorCode})
     and (s.dept_id = #{params.secretaryDeptId} or s.dept_id in (select dept_id from sys_dept where find_in_set(#{params.secretaryDeptId}, ancestors)))


where (s.dept_id = #{deptId}
    or s.dept_id in (select dept_id from sys_dept where find_in_set(#{deptId}, ancestors)))
order by s.student_code


where d.dept_name in (
    select class_name from talk_teacher_class where teacher_code = #{teacherCode}
)
order by s.student_code
